#include <linux/platform_device.h>
#include <linux/mbox_client.h>
#include <linux/mbox_controller.h>
#include <linux/io.h>
#include <linux/clk-provider.h>
#include <linux/err.h>

int hi3660_stub_clk_probe(struct platform_device *pdev)
{
    struct mbox_client *mbox_cl;
    struct mbox_channel *mbox_chan;
    void __iomem *regs;
    struct resource *res;
    int ret;
    struct clk_hw **hw;
    struct clk_onecell_data *data;
    int num_clocks = 8; // Assuming a fixed number of stub clocks

    mbox_cl = devm_kzalloc(&pdev->dev, sizeof(*mbox_cl), GFP_KERNEL);
    if (!mbox_cl)
        return -ENOMEM;

    mbox_cl->dev = &pdev->dev;
    mbox_cl->tx_block = true;

    mbox_chan = mbox_request_channel(mbox_cl, 0);
    if (IS_ERR(mbox_chan))
        return PTR_ERR(mbox_chan);

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    regs = devm_ioremap_resource(&pdev->dev, res);
    if (IS_ERR(regs)) {
        ret = PTR_ERR(regs);
        goto release_mbox;
    }

    hw = devm_kcalloc(&pdev->dev, num_clocks, sizeof(*hw), GFP_KERNEL);
    if (!hw) {
        ret = -ENOMEM;
        goto release_mbox;
    }

    data = devm_kzalloc(&pdev->dev, sizeof(*data), GFP_KERNEL);
    if (!data) {
        ret = -ENOMEM;
        goto release_mbox;
    }

    data->clks = hw;
    data->num = num_clocks;

    ret = devm_of_clk_add_hw_provider(&pdev->dev, of_clk_hw_onecell_get, data);
    if (ret)
        goto release_mbox;

    return 0;

release_mbox:
    mbox_free_channel(mbox_chan);
    return ret;
}

int hi3660_stub_clock_probe(struct platform_device *pdev)
{
    struct mbox_client *client;
    struct mbox_chan *chan;
    void __iomem *regs;
    struct resource *res;
    int ret, i;
    struct hi3660_stub_clock_data *data;

    client = devm_kzalloc(&pdev->dev, sizeof(*client), GFP_KERNEL);
    if (!client)
        return -ENOMEM;

    client->dev = &pdev->dev;
    client->tx_tmo = 1000;
    client->tx_block = false;
    client->rx_callback = NULL;

    chan = mbox_request_channel(client, 0);
    if (IS_ERR(chan)) {
        dev_err(&pdev->dev, "Failed to request mailbox channel\n");
        return PTR_ERR(chan);
    }

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res) {
        ret = -ENODEV;
        goto release_chan;
    }

    regs = devm_ioremap_resource(&pdev->dev, res);
    if (IS_ERR(regs)) {
        ret = PTR_ERR(regs);
        goto release_chan;
    }

    data = devm_kzalloc(&pdev->dev, sizeof(*data), GFP_KERNEL);
    if (!data) {
        ret = -ENOMEM;
        goto release_chan;
    }

    data->regs = regs;
    data->chan = chan;
    data->num_clocks = HI3660_STUB_CLOCK_COUNT;

    for (i = 0; i < data->num_clocks; i++) {
        ret = hi3660_clock_hw_register(pdev, &data->clock_hw[i]);
        if (ret) {
            dev_err(&pdev->dev, "Failed to register clock hardware %d\n", i);
            goto release_chan;
        }
    }

    ret = of_clk_add_provider(pdev->dev.of_node, of_clk_src_onecell_get, data);
    if (ret) {
        dev_err(&pdev->dev, "Failed to add clock provider\n");
        goto release_chan;
    }

    platform_set_drvdata(pdev, data);
    return 0;

release_chan:
    mbox_free_channel(chan);
    return ret;
}

